import React, { useRef, useState } from 'react';
import './App.css';

type Item = { id: string; label: string };
type Side = 'top' | 'bottom';
type Lists = Record<Side, Item[]>;

const INITIAL_LISTS: Lists = {
  top: [
    { id: 'a', label: 'Alpha' },
    { id: 'b', label: 'Beta' },
    { id: 'c', label: 'Gamma' },
    { id: 'd', label: 'Delta' },
    { id: 'e', label: 'Epsilon' }
  ],
  bottom: [
    { id: 'x', label: 'Xenon' },
    { id: 'y', label: 'Yttrium' },
    { id: 'z', label: 'Zinc' }
  ]
};

const TITLES: Record<Side, string> = { top: 'Top', bottom: 'Bottom' };

export default function App() {
  const [lists, setLists] = useState<Lists>(INITIAL_LISTS);
  const [selected, setSelected] = useState<Record<Side, Set<string>>>({ top: new Set(), bottom: new Set() });
  const [search, setSearch] = useState<Record<Side, string>>({ top: '', bottom: '' });
  // Snapshots, because moving items back would not restore their order.
  const [history, setHistory] = useState<Lists[]>([]);
  const [status, setStatus] = useState('');
  const titles = useRef<Record<Side, HTMLDivElement | null>>({ top: null, bottom: null });

  // Only the rows on screen count for select all, the count and the move buttons.
  const visibleRows = (side: Side) => {
    const term = search[side].trim().toLowerCase();
    return lists[side].filter((item) => item.label.toLowerCase().includes(term));
  };

  const selectedRows = (side: Side) => visibleRows(side).filter((item) => selected[side].has(item.id));

  const updateSelection = (side: Side, ids: string[], checked: boolean) => {
    setSelected((current) => {
      const next = new Set(current[side]);
      for (const id of ids) {
        if (checked) next.add(id);
        else next.delete(id);
      }
      return { ...current, [side]: next };
    });
  };

  const move = (from: Side, to: Side) => {
    const moved = selectedRows(from);
    if (moved.length === 0) return;
    const movedIds = moved.map((item) => item.id);

    setHistory((past) => [...past, lists]);
    setLists({
      ...lists,
      [from]: lists[from].filter((item) => !movedIds.includes(item.id)),
      [to]: [...lists[to], ...moved]
    });
    updateSelection(from, movedIds, false);
    setStatus(`${moved.length} ${moved.length === 1 ? 'item' : 'items'} moved to ${TITLES[to]}`);
    // The pressed button may turn off, so focus goes to where the items went.
    titles.current[to]?.focus();
  };

  const undo = () => {
    setLists(history[history.length - 1]);
    setHistory(history.slice(0, -1));
    setSelected({ top: new Set(), bottom: new Set() });
    setStatus('Move undone');
    // The last undo turns this button off.
    if (history.length === 1) titles.current.top?.focus();
  };

  const renderList = (side: Side) => {
    const rows = visibleRows(side);
    const selectedCount = selectedRows(side).length;
    const allSelected = rows.length > 0 && selectedCount === rows.length;

    return (
      <section className="listCard">
        <div className="listHeader">
          <div
            className="listTitle"
            tabIndex={-1}
            ref={(element) => {
              titles.current[side] = element;
            }}
          >
            {TITLES[side]}
          </div>
          <label className="selectAll">
            <input
              className="select-all"
              type="checkbox"
              checked={allSelected}
              disabled={rows.length === 0}
              ref={(element) => {
                if (element) element.indeterminate = selectedCount > 0 && !allSelected;
              }}
              onChange={() => updateSelection(side, rows.map((item) => item.id), !allSelected)}
            />
            <span>Select all</span>
          </label>
        </div>

        <input
          className="list-search"
          type="text"
          placeholder="Search"
          aria-label={`Search ${TITLES[side]}`}
          value={search[side]}
          onChange={(e) => setSearch({ ...search, [side]: e.target.value })}
        />

        <p className="selection-count">{selectedCount} of {rows.length} selected</p>

        <ul className="list" role="list">
          {rows.map((item) => (
            <li key={item.id} className="row">
              <label className="rowLabel">
                <input
                  type="checkbox"
                  checked={selected[side].has(item.id)}
                  onChange={(e) => updateSelection(side, [item.id], e.target.checked)}
                />
                <span>{item.label}</span>
              </label>
            </li>
          ))}
          {rows.length === 0 && (
            <li className="empty">{lists[side].length === 0 ? 'Empty' : 'No matches'}</li>
          )}
        </ul>
      </section>
    );
  };

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Transfer List</h1>
        <p className="subtitle">Select items and move them between lists.</p>

        <div className="layout">
          {renderList('top')}

          <section className="controls">
            <button
              className="btn"
              onClick={() => move('top', 'bottom')}
              disabled={selectedRows('top').length === 0}
              aria-label="move down"
            >
              ↓
            </button>
            <button
              className="btn"
              onClick={() => move('bottom', 'top')}
              disabled={selectedRows('bottom').length === 0}
              aria-label="move up"
            >
              ↑
            </button>
          </section>

          {renderList('bottom')}
        </div>

        <div className="history">
          <button type="button" className="undo-move" onClick={undo} disabled={history.length === 0}>
            Undo
          </button>
          <p className="transfer-status" aria-live="polite">{status}</p>
        </div>
      </section>
    </main>
  );
}

